use std::str::FromStr;
#[derive(Debug, PartialEq)]
struct Port(u16);
impl FromStr for Port {
    type Err = &'static str;
    fn from_str(
        text: &str,
    ) -> Result<Self, Self::Err> {
        let n = text
            .trim()
            .parse::<u16>()
            .map_err(|_| "invalid")?;
        if n == 0 {
            Err("zero")
        } else {
            Ok(Port(n))
        }
    }
}
fn main() {
    assert_eq!(" 8080 ".parse(), Ok(Port(8080)));
}

